function localReconciliationAt(
  tick: number,
  lastProcessedSequence: number,
  xMillimeters: number,
): LocalReconciliationStateV1 {
  return {
    schemaVersion: 1,
    identity: movementIdentity,
    simulationRateHz: 20,
    tick,
    player: {
      id: 'player.1',
      feetPosition: { x: xMillimeters, y: 2_000, z: -3_000 },
      velocity: { x: 250, y: 0, z: 0 },
      integrationRemainders: {
        positionX: 0,
        positionY: 0,
        positionZ: 0,
        planarAcceleration: 0,
        gravity: 0,
      },
      yawMilliDegrees: 28_648,
      pitchMilliDegrees: -5_730,
      lastProcessedSequence,
      ticksSinceAcceptedCommand: 0,
      intent: {
        moveX: 0,
        moveZ: 0,
        heldButtons: 0,
        pressedButtons: 0,
        releasedButtons: 0,
        selectedSlot: 0,
      },
      stance: 'standing',
      locomotion: 'grounded',
      grounded: true,
      support: null,
      coyoteTicksRemaining: 2,
      jumpBufferTicksRemaining: 0,
      slideTicksRemaining: 0,
      slideCooldownTicksRemaining: 0,
      teleportCooldownTicksRemaining: 0,
      standBlocked: false,
      activeVolumes: [],
    },
  };
}

